(function(root){
const tutorialKey=c=>`inkfang-guide-v4-${c.control}-${c.skill}`;
const needsTutorial=(c,read)=>!read(tutorialKey(c),false);
function example(c){const cases={numbers:{target:c.control==='voice'?'98':'ninety-eight',answer:'98',say:'ninety-eight'},mixed:{target:c.control==='voice'?'98':'ninety-eight',answer:'98',say:'ninety-eight'},letters:{target:'B',answer:'B',say:'bee'},words:{target:c.control==='voice'?'CAT':'An animal that says “meow”.',answer:'CAT',say:'cat'},spelling:{target:'PARIS',answer:'PARIS',say:'Paris'},ipa:{target:'/kæt/',answer:'CAT',say:'cat'}};return cases[c.skill]||cases.numbers;}
function guidePages(c){const e=example(c),numeric=['numbers','mixed'].includes(c.skill);const first=c.control==='voice'?{title:'Look. Then say it.',text:c.skill==='ipa'?'Read the IPA transcription and say the whole word. /kæt/ is “cat”.':c.skill==='letters'?'Say the letter’s name aloud. For B, say “bee”.':`Say the ${numeric?'number':'word'} shown. You can name several visible targets in one phrase.`}:{title:numeric?'Read the number words.':'Read your target.',text:numeric?'A monster shows “ninety-eight”. Your answer is 98 — digits only. Typing the number words does not count.':c.skill==='words'?'Read the clue and work out the word. An animal that says “meow” is CAT.':'Read the name or place and spell it with CAPITAL letters.'};const second=c.control==='type'?{title:numeric?'Type digits, not words.':'Type the full answer.',text:`Switch to an English keyboard and turn off UniKey / Vietnamese input first. Type ${e.answer}. A complete answer fires immediately unless it could still become another active target. A brief 220 ms pause resolves that ambiguity. Enter also fires.`}:{title:'Say a string of answers.',text:`Allow microphone access and say “${e.say}”. Name several targets in a row to attack them together. Stable speech updates can fire before the browser finishes the sentence.`};const third={title:c.control==='voice'?'A fairer voice swarm.':'Hit. Keep moving.',text:c.control==='voice'?'Speaking has fewer, slower monsters and a short grace period at the danger line. If the microphone reconnects, monsters and the timer wait. Recognition speed still depends on your browser and connection.':`Protect five hearts. Monsters keep coming, and each 20-second wave gets faster. ${c.skill==='mixed'?'Mixed typing combines numbers and vocabulary, with no single-letter targets.':'Music automatically follows the pace of the swarm.'}`};return[first,second,third];}
function badgeFor({kills,bestCombo}){if(kills>=30&&bestCombo>=12)return{name:'INK LEGEND',glyph:'S',goal:50};if(kills>=20)return{name:'SWARM BREAKER',glyph:'A',goal:30};if(kills>=10)return{name:'LINE GUARD',glyph:'B',goal:20};return{name:'ROOKIE RISING',glyph:'C',goal:10};}
root.InkOnboarding={tutorialKey,needsTutorial,example,guidePages,badgeFor};if(typeof module!=='undefined')module.exports=root.InkOnboarding;
})(typeof window!=='undefined'?window:globalThis);
